record BoxIter<T> {
    v: T
}

impl<T> Iterator<T> for BoxIter<T> {
    fn next(mut self) -> Option<T> {
        return None
    }
    fn map<U>(mut self, f: fn(U) -> T) -> Dyn<Iterator<U> > {
        return Dyn<Iterator<U> >(BoxIter { v: self.v })
    }
}

